import { useCallback, useEffect, useState } from "react";
import {
  CheckCircle2,
  CircleDashed,
  Download,
  FileText,
  Loader2,
  Pencil,
  Play,
  Plus,
  Radar,
  Trash2,
  Upload,
  X,
  XCircle,
} from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  DeleteDeployment,
  DeployDestroyPreview,
  DeployPlanPreview,
  DeployPresets,
  GetDeployment,
  GetRunLog,
  ImportDeploymentBundle,
  ListDeployments,
  RunDetect,
  SaveDeployment,
  StartApply,
  StartDestroy,
} from "../../wailsjs/go/controllers/Deployments";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  ExportDeploymentBundle,
} from "../../wailsjs/go/controllers/Deployments";
// @ts-ignore wailsjs bindings are generated by wails build
import { ReadLocalTextFile, WriteLocalTextFile } from "../../wailsjs/go/controllers/SSH";
// @ts-ignore wailsjs bindings are generated by wails build
import { EventsOn, OpenFileDialog, SaveFileDialog } from "../../wailsjs/runtime";
import DocumentEditor from "../components/documents/DocumentEditor";
import { useDialogs } from "../components/dialogs/DialogProvider";
import { useT } from "../lib/i18n";

type RunSummary = {
  id: string;
  kind: string;
  status: string;
  startedAt: string;
  endedAt: string;
  error?: string;
};

type DeploymentRecord = {
  id: string;
  name: string;
  updatedAt: string;
  runs?: RunSummary[];
};

type ApplyConfig = {
  projectName: string;
  kind: string;
  domain: string;
  environment: string;
  gitUrl: string;
  gitBranch: string;
  gitPat: string;
  webServer: string;
  phpVersion: string;
  database: {
    engine: string;
    name: string;
    user?: string;
    password?: string;
    accessHost?: string;
    accessPort?: number;
  };
  ssl: { enabled: boolean; email: string };
};

type View = {
  id: string;
  name: string;
  hostName: string;
  presetId: string;
  config: ApplyConfig;
  runs?: RunSummary[];
};

type Step = { title: string; command: string; sudo: boolean; ignore: boolean };

type ActiveRun = {
  deploymentId: string;
  runId: string;
  kind: "apply" | "destroy";
  steps: Record<number, { title: string; status: string }>;
  lines: string[];
};

const EMPTY_CONFIG: ApplyConfig = {
  projectName: "",
  kind: "laravel",
  gitPat: "",
  domain: "",
  environment: "production",
  gitUrl: "",
  gitBranch: "main",
  webServer: "nginx",
  phpVersion: "8.3",
  database: { engine: "mysql", name: "" },
  ssl: { enabled: false, email: "" },
};

// The deployments page: cards per deployment, an editor with a redacted
// plan preview and script preview, live run timelines (apply and destroy),
// run logs, and bundle import/export.
export default function Deployments() {
  const t = useT();
  const dialogs = useDialogs();
  const [records, setRecords] = useState<DeploymentRecord[]>([]);
  const [editing, setEditing] = useState<View | null>(null);
  const [hosts, setHosts] = useState<string[]>([]);
  const [presets, setPresets] = useState<{ id: string; name: string }[]>([]);
  const [activeRun, setActiveRun] = useState<ActiveRun | null>(null);
  const [logRunId, setLogRunId] = useState("");
  const [logText, setLogText] = useState("");
  const [importReport, setImportReport] = useState<string>("");

  const refresh = useCallback(() => {
    ListDeployments()
      .then((list: DeploymentRecord[]) => setRecords(list ?? []))
      .catch(() => {
        /* pre-startup */
      });
    DeployPresets()
      .then((list: { id: string; name: string }[]) => setPresets(list ?? []))
      .catch(() => {});
    import("../../wailsjs/go/controllers/SSH")
      .then((m) => m.ListHosts())
      .then((list: { name: string }[]) => setHosts((list ?? []).map((h) => h.name)))
      .catch(() => {});
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Stream the active run's timeline. Events carry the deployment ID in
  // their name, so exactly one subscription set is live at a time.
  useEffect(() => {
    if (!activeRun) return;
    const base = `deployment:${activeRun.kind}`;
    const id = activeRun.deploymentId;
    const patch = (fn: (prev: ActiveRun) => ActiveRun) => {
      setActiveRun((prev) => (prev && prev.runId === activeRunIdRef.current ? fn(prev) : prev));
    };
    const activeRunIdRef = { current: activeRun.runId };

    // @ts-ignore EventsOn returns a cancel function
    const c1 = EventsOn(`${base}:step:${id}`, (p: { runId: string; index: number; title: string; status: string }) => {
      if (p.runId !== activeRunIdRef.current) return;
      patch((prev) => ({
        ...prev,
        steps: { ...prev.steps, [p.index]: { title: p.title, status: p.status } },
      }));
    });
    // @ts-ignore EventsOn returns a cancel function
    const c2 = EventsOn(`${base}:line:${id}`, (p: { runId: string; line: string }) => {
      if (p.runId !== activeRunIdRef.current) return;
      patch((prev) => ({ ...prev, lines: [...prev.lines.slice(-400), p.line] }));
    });
    // @ts-ignore EventsOn returns a cancel function
    const c3 = EventsOn(`${base}:done:${id}`, (p: { runId: string; status: string; error: string }) => {
      if (p.runId !== activeRunIdRef.current) return;
      patch((prev) => ({
        ...prev,
        lines: [...prev.lines, p.status === "success" ? "✔ done" : `✘ ${p.error}`],
      }));
      refresh();
    });
    return () => {
      c1?.();
      c2?.();
      c3?.();
    };
  }, [activeRun?.deploymentId, activeRun?.kind, activeRun?.runId, refresh]); // eslint-disable-line react-hooks/exhaustive-deps

  const edit = async (id: string) => {
    try {
      setEditing((await GetDeployment(id)) as unknown as View);
    } catch (error) {
      await dialogs.alert({ title: id, message: String(error) });
    }
  };

  const create = () => {
    setEditing({
      id: "",
      name: "",
      hostName: hosts[0] ?? "",
      presetId: "",
      config: { ...EMPTY_CONFIG },
    });
  };

  const save = async (view: View) => {
    try {
      await SaveDeployment(view as any);
      setEditing(null);
      refresh();
    } catch (error) {
      await dialogs.alert({ title: view.name, message: String(error) });
    }
  };

  const remove = async (rec: DeploymentRecord) => {
    const yes = await dialogs.confirm({
      title: t("deployments.deleteConfirm", { name: rec.name }),
      danger: true,
    });
    if (!yes) return;
    await DeleteDeployment(rec.id);
    refresh();
  };

  const detect = async (rec: DeploymentRecord) => {
    try {
      await RunDetect(rec.id);
      refresh();
      const view = await GetDeployment(rec.id);
      const latest = view.runs?.[0];
      if (latest) {
        setLogRunId(latest.id);
        setLogText(await GetRunLog(latest.id));
      }
    } catch (error) {
      await dialogs.alert({ title: rec.name, message: String(error) });
    }
  };

  const apply = async (rec: DeploymentRecord) => {
    try {
      const runId = await StartApply(rec.id);
      setActiveRun({ deploymentId: rec.id, runId, kind: "apply", steps: {}, lines: [] });
    } catch (error) {
      await dialogs.alert({ title: rec.name, message: String(error) });
    }
  };

  const destroy = async (rec: DeploymentRecord) => {
    const dropDB = await dialogs.confirm({
      title: t("deployments.destroyConfirm", { name: rec.name }),
      message: t("deployments.destroyDropDb"),
      danger: true,
    });
    // The dialog answers "drop the database too?": Cancel still destroys,
    // but keeps the database — both paths need a second explicit go.
    const proceed = await dialogs.confirm({
      title: t("deployments.destroyTitle", { name: rec.name }),
      message: t("deployments.destroyWarning"),
      danger: true,
    });
    if (!proceed) return;
    try {
      const runId = await StartDestroy(rec.id, dropDB);
      setActiveRun({ deploymentId: rec.id, runId, kind: "destroy", steps: {}, lines: [] });
    } catch (error) {
      await dialogs.alert({ title: rec.name, message: String(error) });
    }
  };

  const openLog = async (run: RunSummary) => {
    setLogRunId(run.id);
    setLogText(await GetRunLog(run.id));
  };

  const exportBundle = async () => {
    const target = await SaveFileDialog({
      Title: t("deployments.exportBundle"),
      DefaultFilename: "kitodock-bundle.json",
    });
    if (!target) return;
    try {
      const json = await ExportDeploymentBundle(null);
      await WriteLocalTextFile(target, json);
      setImportReport(t("deployments.exportDone"));
    } catch (error) {
      await dialogs.alert({ title: t("deployments.exportBundle"), message: String(error) });
    }
  };

  const importBundle = async () => {
    const source = await OpenFileDialog({
      Title: t("deployments.importBundle"),
      Filters: [{ DisplayName: "Kitodock bundle", Pattern: "*.json" }],
    });
    if (!source) return;
    try {
      const json = await ReadLocalTextFile(source);
      const result = await ImportDeploymentBundle(json);
      const conflicts = Object.entries(result.hostConflicts ?? {})
        .map(([name, addr]) => `${name} → ${addr}`)
        .join(", ");
      setImportReport(
        t("deployments.importReport", {
          hostsAdded: result.hostsAdded,
          deploymentsAdded: result.deploymentsAdded,
          skipped: result.hostsSkipped + result.deploymentsSkipped,
        }) + (conflicts ? ` · ${t("deployments.importConflicts")}: ${conflicts}` : "")
      );
      refresh();
    } catch (error) {
      await dialogs.alert({ title: t("deployments.importBundle"), message: String(error) });
    }
  };

  return (
    <div className="flex h-full min-h-0 flex-col">
      <header className="flex items-center justify-between">
        <h1 className="text-lg font-semibold text-white/95">{t("deployments.title")}</h1>
        <div className="flex items-center gap-1.5">
          <button
            type="button"
            onClick={() => void importBundle()}
            title={t("deployments.importBundle")}
            className="rounded-md border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
          >
            <Upload className="h-3.5 w-3.5" />
          </button>
          <button
            type="button"
            onClick={() => void exportBundle()}
            title={t("deployments.exportBundle")}
            className="rounded-md border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
          >
            <Download className="h-3.5 w-3.5" />
          </button>
          <button
            type="button"
            onClick={create}
            disabled={hosts.length === 0}
            title={hosts.length === 0 ? t("deployments.needHost") : undefined}
            className="flex items-center gap-1.5 rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent/85 disabled:opacity-40"
          >
            <Plus className="h-3.5 w-3.5" /> {t("deployments.new")}
          </button>
        </div>
      </header>

      {importReport && (
        <p className="mt-2 rounded border border-accent2/30 bg-accent2/5 px-3 py-1.5 text-[11px] text-accent2">
          {importReport}
        </p>
      )}

      <div className="mt-3 min-h-0 flex-1 space-y-3 overflow-y-auto pr-0.5">
        {editing && (
          <DeploymentForm
            view={editing}
            hosts={hosts}
            presets={presets}
            onSave={save}
            onCancel={() => setEditing(null)}
          />
        )}

        {records.length === 0 && !editing && (
          <section className="glass p-8 text-center">
            <p className="text-sm text-white/50">{t("deployments.empty")}</p>
          </section>
        )}

        {records.map((rec) => (
          <article key={rec.id} className="glass p-3">
            <div className="flex items-center gap-3">
              <div className="min-w-0 flex-1">
                <span className="truncate text-sm font-medium text-white/90">{rec.name}</span>
                {rec.runs && rec.runs.length > 0 && (
                  <p className="mt-0.5 flex items-center gap-1.5 text-[11px] text-white/40">
                    <StatusIcon status={rec.runs[0].status} />
                    {t(`deployments.kind.${rec.runs[0].kind}`)} ·{" "}
                    {new Date(rec.runs[0].startedAt).toLocaleString()}
                  </p>
                )}
              </div>
              <div className="flex shrink-0 items-center gap-1">
                <button
                  type="button"
                  onClick={() => void detect(rec)}
                  title={t("deployments.detect")}
                  className="rounded border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
                >
                  <Radar className="h-3 w-3" />
                </button>
                <button
                  type="button"
                  onClick={() => void apply(rec)}
                  title={t("deployments.apply")}
                  className="rounded border border-emerald-400/30 bg-emerald-500/10 p-1.5 text-emerald-300 hover:bg-emerald-500/20"
                >
                  <Play className="h-3 w-3" />
                </button>
                <button
                  type="button"
                  onClick={() => void edit(rec.id)}
                  title={t("deployments.edit")}
                  className="rounded border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
                >
                  <Pencil className="h-3 w-3" />
                </button>
                <button
                  type="button"
                  onClick={() => void destroy(rec)}
                  title={t("deployments.destroy")}
                  className="rounded border border-red-400/30 bg-red-500/10 p-1.5 text-red-300 hover:bg-red-500/20"
                >
                  <Trash2 className="h-3 w-3" />
                </button>
              </div>
            </div>

            {rec.runs && rec.runs.length > 0 && (
              <div className="mt-2 flex flex-wrap gap-1 border-t border-white/5 pt-2">
                {rec.runs.slice(0, 8).map((run) => (
                  <button
                    key={run.id}
                    type="button"
                    onClick={() => void openLog(run)}
                    title={new Date(run.startedAt).toLocaleString()}
                    className={`flex items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] ${
                      logRunId === run.id
                        ? "border-accent2/60 text-accent2"
                        : "border-white/10 text-white/40 hover:border-white/25 hover:text-white/70"
                    }`}
                  >
                    <StatusIcon status={run.status} />
                    {t(`deployments.kind.${run.kind}`)}
                  </button>
                ))}
              </div>
            )}
          </article>
        ))}

        {activeRun && (
          <section className="glass overflow-hidden">
            <div className="flex items-center justify-between border-b border-white/10 px-3 py-2">
              <span className="flex items-center gap-2 font-mono text-[11px] text-white/60">
                <Loader2 className="h-3 w-3 animate-spin text-accent2" />
                {activeRun.kind === "destroy"
                  ? t("deployments.destroyRunning")
                  : t("deployments.running")}
              </span>
              <button
                type="button"
                onClick={() => setActiveRun(null)}
                className="rounded border border-white/10 p-1 text-white/60 hover:bg-white/10 hover:text-white"
              >
                <X className="h-3 w-3" />
              </button>
            </div>
            <div className="space-y-1 border-b border-white/5 px-3 py-2">
              {Object.entries(activeRun.steps).map(([index, step]) => (
                <div key={index} className="flex items-center gap-2 text-[11px]">
                  <StatusIcon status={step.status} />
                  <span
                    className={
                      step.status === "error"
                        ? "text-red-300"
                        : step.status === "ok"
                          ? "text-white/70"
                          : "text-white/90"
                    }
                  >
                    {step.title}
                  </span>
                </div>
              ))}
            </div>
            <pre className="max-h-48 overflow-auto bg-black/30 px-3 py-2 font-mono text-[10px] leading-relaxed text-white/60">
              {activeRun.lines.join("\n")}
            </pre>
          </section>
        )}

        {logRunId && logText && (
          <section className="glass overflow-hidden">
            <div className="flex items-center justify-between border-b border-white/10 px-3 py-2">
              <span className="flex items-center gap-2 font-mono text-[11px] text-white/60">
                <FileText className="h-3 w-3" /> {t("deployments.runLog")}
              </span>
              <button
                type="button"
                onClick={() => {
                  setLogRunId("");
                  setLogText("");
                }}
                className="rounded border border-white/10 p-1 text-white/60 hover:bg-white/10 hover:text-white"
              >
                <X className="h-3 w-3" />
              </button>
            </div>
            <pre className="max-h-64 overflow-auto bg-black/30 px-3 py-2 font-mono text-[10px] leading-relaxed text-white/60">
              {logText}
            </pre>
          </section>
        )}
      </div>
    </div>
  );
}

function StatusIcon({ status }: { status: string }) {
  switch (status) {
    case "success":
    case "ok":
      return <CheckCircle2 className="h-3 w-3 shrink-0 text-emerald-400" />;
    case "error":
      return <XCircle className="h-3 w-3 shrink-0 text-red-400" />;
    case "running":
      return <Loader2 className="h-3 w-3 shrink-0 animate-spin text-accent2" />;
    case "ignored":
      return <CircleDashed className="h-3 w-3 shrink-0 text-white/30" />;
    default:
      return <CircleDashed className="h-3 w-3 shrink-0 text-white/30" />;
  }
}

function DeploymentForm({
  view,
  hosts,
  presets,
  onSave,
  onCancel,
}: {
  view: View;
  hosts: string[];
  presets: { id: string; name: string }[];
  onSave: (view: View) => void;
  onCancel: () => void;
}) {
  const t = useT();
  const [draft, setDraft] = useState<View>(view);
  const [steps, setSteps] = useState<Step[]>([]);
  const [showScript, setShowScript] = useState(false);
  const [script, setScript] = useState("");

  useEffect(() => {
    DeployPlanPreview(draft as any)
      .then((list: Step[]) => setSteps(list ?? []))
      .catch(() => setSteps([]));
  }, [draft]);

  // The resolved preset script (or the generated plan joined) for the
  // Monaco preview.
  useEffect(() => {
    if (!showScript) return;
    DeployPlanPreview(draft as any)
      .then((list: Step[]) =>
        setScript(
          (list ?? [])
            .map((s, i) => `# ${i + 1}. ${s.title}${s.sudo ? " (sudo)" : ""}\n${s.command}`)
            .join("\n\n")
        )
      )
      .catch(() => setScript(""));
  }, [showScript, draft]);

  const set = (patch: Partial<View>) => setDraft((d) => ({ ...d, ...patch }));
  const setConfig = (patch: Partial<ApplyConfig>) =>
    setDraft((d) => ({ ...d, config: { ...d.config, ...patch } }));

  const valid =
    draft.name.trim() !== "" &&
    draft.hostName !== "" &&
    draft.config.projectName.trim() !== "" &&
    draft.config.domain.trim() !== "";

  return (
    <section className="glass space-y-3 p-4">
      <div className="grid grid-cols-3 gap-3">
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.name")}</span>
          <input
            className="input w-full"
            value={draft.name}
            onChange={(e) => set({ name: e.target.value })}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.host")}</span>
          <select
            className="input w-full"
            value={draft.hostName}
            onChange={(e) => set({ hostName: e.target.value })}
          >
            <option value="">—</option>
            {hosts.map((h) => (
              <option key={h} value={h}>
                {h}
              </option>
            ))}
          </select>
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.preset")}</span>
          <select
            className="input w-full"
            value={draft.presetId}
            onChange={(e) => set({ presetId: e.target.value })}
          >
            <option value="">{t("deployments.presetGenerated")}</option>
            {presets.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
        </label>
      </div>

      <div className="grid grid-cols-4 gap-3">
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.project")}</span>
          <input
            className="input w-full font-mono"
            value={draft.config.projectName}
            onChange={(e) => setConfig({ projectName: e.target.value })}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.domain")}</span>
          <input
            className="input w-full font-mono"
            placeholder="app.example.com"
            value={draft.config.domain}
            onChange={(e) => setConfig({ domain: e.target.value })}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.environment")}</span>
          <select
            className="input w-full"
            value={draft.config.environment}
            onChange={(e) => setConfig({ environment: e.target.value })}
          >
            <option value="production">production</option>
            <option value="staging">staging</option>
            <option value="development">development</option>
          </select>
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.kindLabel")}</span>
          <select
            className="input w-full"
            value={draft.config.kind}
            onChange={(e) => setConfig({ kind: e.target.value })}
          >
            <option value="laravel">Laravel</option>
            <option value="static">Static</option>
          </select>
        </label>
      </div>

      <div className="grid grid-cols-4 gap-3">
        <label className="col-span-2 space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.gitUrl")}</span>
          <input
            className="input w-full font-mono"
            placeholder="https://github.com/user/repo.git"
            value={draft.config.gitUrl}
            onChange={(e) => setConfig({ gitUrl: e.target.value })}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.branch")}</span>
          <input
            className="input w-full font-mono"
            value={draft.config.gitBranch}
            onChange={(e) => setConfig({ gitBranch: e.target.value })}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.php")}</span>
          <input
            className="input w-full font-mono"
            value={draft.config.phpVersion}
            onChange={(e) => setConfig({ phpVersion: e.target.value })}
          />
        </label>
      </div>

      <div className="grid grid-cols-3 gap-3">
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.dbEngine")}</span>
          <select
            className="input w-full"
            value={draft.config.database.engine}
            onChange={(e) => setConfig({ database: { ...draft.config.database, engine: e.target.value } })}
          >
            <option value="mysql">MySQL</option>
            <option value="postgres">PostgreSQL</option>
            <option value="">{t("deployments.dbNone")}</option>
          </select>
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("deployments.dbName")}</span>
          <input
            className="input w-full font-mono"
            value={draft.config.database.name}
            onChange={(e) => setConfig({ database: { ...draft.config.database, name: e.target.value } })}
          />
        </label>
        <label className="flex items-end gap-2 pb-1.5 text-xs text-white/60">
          <input
            type="checkbox"
            checked={draft.config.ssl.enabled}
            onChange={(e) => setConfig({ ssl: { ...draft.config.ssl, enabled: e.target.checked } })}
            className="h-3.5 w-3.5"
          />
          {t("deployments.ssl")}
        </label>
      </div>

      {steps.length > 0 && (
        <div className="space-y-1.5">
          <button
            type="button"
            onClick={() => setShowScript((v) => !v)}
            className="text-[11px] text-white/50 hover:text-white/80"
          >
            {t("deployments.planPreview", { count: steps.length })} ·{" "}
            {showScript ? t("deployments.hideScript") : t("deployments.showScript")}
          </button>
          {!showScript && (
            <ol className="space-y-1 rounded border border-white/10 px-3 py-2">
              {steps.map((step, i) => (
                <li key={i} className="font-mono text-[10px] text-white/50">
                  {i + 1}. {step.title}
                  {step.sudo ? " (sudo)" : ""}
                </li>
              ))}
            </ol>
          )}
          {showScript && (
            <div className="h-72 overflow-hidden rounded border border-white/10">
              <DocumentEditor value={script} language="shell" readOnly />
            </div>
          )}
        </div>
      )}

      <div className="flex justify-end gap-2 pt-2">
        <button
          type="button"
          onClick={onCancel}
          className="rounded-md border border-white/10 px-3 py-1.5 text-xs text-white/70 hover:bg-white/10"
        >
          {t("dialog.cancel")}
        </button>
        <button
          type="button"
          disabled={!valid}
          onClick={() => onSave(draft)}
          className="rounded-md bg-accent px-4 py-1.5 text-xs font-medium text-white disabled:opacity-40"
        >
          {t("dialog.save")}
        </button>
      </div>
    </section>
  );
}
